  _ = `Adicionar pacotes`,
  _ = `Remover todos os pacotes deste conjunto.`,
  _ = `Remover o pacote "%1$s" deste conjunto.`,
  _ = `Comece a digitar para filtrar a lista de pacotes.`,
  _ = `Observe que esses não são IDs de aplicativo, mas sim pacotes da loja que serão usados para vender o produto na Loja Steam.`,
  _ = `Informe o nome ou ID do pacote aqui`,
  _ = `Selecione um ou mais pacotes abaixo e clique em "Continuar" para adicioná-los ao seu conjunto.`,
  _ = `Conjunto colaborativo`,
  _ = `Opcional: você pode convidar outros desenvolvedores a incluir os seus jogos no conjunto. Como dono(a) do conjunto, você é responsável pela coordenação dos outros desenvolvedores. Você também é a única pessoa com permissões para publicar o conjunto na Loja Steam. Os convidados escolherão quais jogos ou pacotes querem incluir. Cada vez que um pacote é adicionado ao conjunto ou o percentual de desconto é alterado, todos os colaboradores precisam aprovar os seus jogos para inclusão ao conjunto antes que o mesmo seja publicado.`,
  _ = `Convite recebido via código de amigo`,
  _ = `Limitações de visibilidade`,
  _ = `Não há limitações de visibilidade causadas pelo preço ou desconto atual do jogo. `,
  _ = `Pode ser necessário ajustar o preço do jogo em certas moedas ou o percentual de desconto aplicado ao conjunto.`,
  _ = `Deseja descartar as alterações não salvas?`,
  _ = `Painel das páginas de promoção`,
  _ = `Páginas de eventos promocionais`,
  _ = `Aqui, você encontrará as páginas promocionais no Steam que contêm um ou mais jogos dos quais você possui permissão de gerenciamento. Algumas dessas páginas são organizadas pelos organizadores do evento e outras pela Valve como parte de eventos promocionais organizados.`,
  _ = `Todas as páginas de promoções ativas e salvas criadas tanto pela Valve quanto por colaboradores externos aprovados. Para que um novo parceiro possa criar uma página de promoção, %1$s. Você pode enviar %2$s para o seu parceiro.`,
  _ = `leia este guia`,
  _ = `a documentação externa deste recurso`,
  _ = `Resumo`,
  _ = `Promoções ativas: %1$s`,
  _ = `Páginas de promoções sazonais futuras em destaque: %1$s`,
  _ = `Essas são as páginas promocionais que estão planejadas para serem destacadas na página inicial da Loja Steam durante a próxima promoção sazonal (considerando que os jogos inclusos estarão em oferta). Não se esqueça de incluir todos os títulos relevantes da sua série.`,
  _ = `Links`,
  _ = `Promoções futuras publicadas: %1$s`,
  _ = `Rascunhos: %1$s`,
  _ = `Páginas promocionais em andamento e atualmente ocultas/não publicadas.`,
  _ = `Rascunhos antigos: %1$s`,
  _ = `Rascunhos sem alterações há mais de um mês.`,
  _ = `Promoções passadas: %1$s`,
  _ = `Data de início da promoção`,
  _ = `Data de término da promoção`,
  _ = `Navegação rápida pelos jogos inclusos`,
  _ = `Esta é uma lista dos seus jogos que participarão do evento.`,
  _ = `Explorar`,
  _ = `O evento está oculto e você não tem permissão para editá-lo, mas alguém da sua equipe tem. Para saber quem, passe o mouse sobre o ícone do grupo abaixo e clique em "Ver lista de membros". Por padrão, os membros administradores do grupo terão permissão para editar o evento.`,
  _ = `Este evento ainda não está visível publicamente, mas você pode vê-lo por ter um jogo listado na página promocional. Caso isso seja inesperado, entre em contato com os organizadores da promoção.`,
  _ = `Entidade organizadora:`,
  _ = `Contato da entidade organizadora:`,
  _ = `Dados de contato indisponíveis`,
  _ = `Pré-visualizar evento`,
  _ = `Ver página da promoção na loja`,
  _ = `Editar evento`,
  _ = `Página de estatísticas`,
  _ = `Seções da promoção: %1$s`,
  _ = `Sem dados`,
  _ = `Aplicativos`,
  _ = `A quantidade de aplicativos inclusos em qualquer parte da página da promoção.`,
  _ = `Seus aplicativos`,
  _ = `A quantidade de aplicativos seus inclusos em qualquer parte da página da promoção. Clique para ver a lista dos seus jogos inclusos.`,
  _ = `Conjuntos: %1$s`,
  _ = `Aplicativos: %1$s`,
  _ = `Pacotes: %1$s`,
  _ = `Por que estou vendo isto?`,
  _ = `%1$s dos seus aplicativos foi incluído nesta página promocional. Caso não tenha recebido um convite para participar deste evento, entre em contato com o organizador.`,
  _ = `%1$s dos seus aplicativos foram incluídos nesta página promocional. Caso não tenha recebido um convite para participar deste evento, entre em contato com o organizador.`,
