  _ = `Aviso: já há um desconto de %1$s % no ar`,
  _ = `Criar oferta do dia`,
  _ = `Duração (%1$s a %2$s dias)`,
  _ = `Duração`,
  _ = `Já existe um desconto agendado para este jogo para %1$s dias mais tarde. A duração máxima do desconto é de %2$s dias.`,
  _ = `A %2$s começa em %3$s. Caso deseje participar, a duração do desconto da oferta do dia não pode ser superior a %1$s dia.`,
