  _ = `Consultar documentação`,
  _ = `Selecione os pacotes aos quais aplicar o desconto (pelo menos um):`,
  _ = `O intervalo entre descontos ativo termina em %1$s`,
  _ = `Item em destaque:`,
  _ = `O "item em destaque" será exibido na seção de ofertas do dia junto ao preço, porcentagem de desconto e imagem de cápsula. Na maioria dos casos, use o jogo em si (que é a seleção padrão).`,
