  _ = `Este convite foi cancelado`,
  _ = `Como os convites funcionam?`,
  _ = `Caso o seu jogo seja convidado para participar das ofertas do dia, ele será listado acima e você receberá um e-mail. Depois, o processo funcionará da seguinte forma:`,
  _ = `Selecione uma data disponível nos próximos seis meses que seja adequada para você.`,
  _ = `A visibilidade na página inicial e em páginas de marcadores aplicáveis da Loja Steam dura 24 horas, e o desconto ficará no ar entre 7 e 14 dias dependendo da duração selecionada. A oferta começará às 10h da data selecionada (horário do Pacífico).`,
  _ = `Ao selecionar uma data disponível, será solicitado que informe a porcentagem de desconto e selecione os pacotes que farão parte da promoção.`,
  _ = `Pedimos que escolha uma % de desconto que seja igual ou superior ao maior que tenha oferecido no passado.`,
