  _ = `Melhores práticas para ofertas do dia`,
  _ = `Descobrimos que é uma boa ideia casar o aumento de visibilidade e o desconto com outras atividades que esteja planejando, como uma atualização de conteúdo para o jogo, transmissão ao vivo ou evento da comunidade.`,
  _ = `Caso planeje oferecer outros descontos em até um mês antes da sua oferta do dia, tente usar a mesma porcentagem. Quando destacarmos o seu jogo como uma oferta do dia, queremos que ela seja tão boa ou melhor que as ofertas que você disponibilizou no passado.`,
