  _ = `Antitrapaça`,
  _ = `Caso o seu jogo instale um serviço antitrapaça a nível do kernel no lado dos clientes, é obrigatório divulgar essa informação aos usuários aqui. Se você tiver a sua própria solução antitrapaça, ou a solução não estiver na lista abaixo, selecione "outro" e informe os dados.`,
  _ = `Caso o seu jogo use um serviço antitrapaça que não se integre ao kernel do sistema, seja ele no lado do cliente ou servidor, este campo é opcional, mas geralmente acreditamos que todo jogo que usa um serviço antitrapaça se beneficie da divulgação dessa informação para os usuários.`,
  _ = `Serviço antitrapaça:`,
  _ = `Integração a nível de kernel`,
  _ = `Esta solução antitrapaça envolve a instalação ou modificação de arquivos a nível do kernel do sistema operacional.`,
