  _ = `Desinstalação completa`,
  _ = `Selecione apenas caso possa confirmar que todos os arquivos relacionados à solução antitrapaça instalados pelo seu jogo são removidos do sistema quando o jogo é desinstalado.`,
  _ = `Proteção de inicialização exigida`,
  _ = `Caso o jogo exija o uso de Inicialização Segura (Secure Boot), um módulo confiável de plataforma (TPM) instalado ou a ativação de outras medidas de proteção de inicialização para acessar um ou mais modos de jogo, selecione a combinação exigida.`,
