  _ = `Envie uma imagem comparativa das edições selecionadas, de dimensões %1$s × %2$s px. Ela será exibida em uma janela de diálogo quando o usuário clicar em "Comparar edições" na página do aplicativo na loja. Use o menu suspenso de idiomas para enviar versões traduzidas da imagem.`,
