  _ = `Lembre-se de <1>publicar</1> as alterações.`,
  _ = `As imagens comparativas devem ter %1$s x %2$s px de tamanho. Tamanho da imagem fornecida: %3$s x %4$s px.`,
  _ = `As edições devem incluir o jogo base ("%1$s", pacote de ID %2$s).`,
