  _ = `(Edite a lista das artes de cápsula exibidas neste pacote na página "Editar pacote da loja" abaixo.)`,
  _ = `Isso adicionará as artes de cápsula à seção de compra do pacote na loja, de forma similar a um conjunto. A cápsula do aplicativo base será exibida primeiro, seguida pelos outros aplicativos em ordem decrescente de preço.`,
  _ = `Omitir nome do jogo do início dos nomes dos itens na listagem do pacote.`,
  _ = `Para reduzir a redundância e melhorar a legibilidade, omitir o nome do jogo, bem como espaços em branco e caracteres de conexão (como dois pontos e travessões), no início do nome de itens como conteúdos adicionais e trilhas sonoras quando listados na seção de compra do pacote. Por exemplo, "Half-Life 2: Episode One" será exibido apenas como "Episode One". Apenas o nome exato do jogo base seguido de espaços em branco e separadores comuns (como dois pontos e travessão) serão ocultos.`,
  _ = `Salvar e publicar`,
  _ = `Cancelar`,
  _ = `Evento de grande atualização em destaque`,
  _ = `Os usuários que possuem o jogo serão redirecionados ao evento na biblioteca para verem o contexto. Buscamos eventos associados ao jogo base.`,
