  _ = `Gerenciamento de descontos`,
  _ = `As datas das promoções estão sujeitas a alterações. Tenha cuidado ao anunciar datas publicamente, especialmente para eventos que ocorrerão em um futuro distante.`,
  _ = `Observações`,
  _ = `Lembre-se: não é possível enviar qualquer desconto nos 30 dias após um jogo ser lançado pela primeira vez sem desconto ou um aumento de preço em qualquer moeda. Para informações detalhadas, consulte a %1$s.`,
  _ = `documentação`,
