  _ = `Importar/Exportar descontos`,
  _ = `Ferramentas`,
  _ = `Importar/Exportar CSV...`,
  _ = `Também é possível ajustar os descontos dos pacotes através de um arquivo CSV, que pode ser útil caso precise atualizar muitos descontos ao mesmo tempo ou precise verificar a consistência em um grande catálogo de jogos.`,
