  _ = `O desconto agendado fará com que o preço deste pacote fique abaixo do mínimo obrigatório em uma ou mais moedas, portanto, não será possível comprá-lo nas regiões que usam as moedas afetadas. Para garantir que o pacote possa ser comprado em todas as moedas, informe um percentual de desconto inferior a %1$s% para ele.`,
