  _ = `(Claro, eles serão atualizados com a nova porcentagem e mensagem se necessário.)`,
  _ = `Sim, usem os mesmos recursos gráficos.`,
  _ = `Não, eu vou enviar recursos gráficos novos.`,
  _ = `Recursos gráficos exigidos:`,
  _ = `Oferta do meio da semana`,
  _ = `Oferta do fim de semana`,
  _ = `Destaque de promoção`,
