  _ = `Banner sob o carrossel (dispositivos móveis)`,
  _ = `Banner na parte superior da página (dispositivos móveis)`,
  _ = `Mensagem pop-up de divulgação`,
  _ = `Mensagem pop-up de divulgação`,
  _ = `Mensagem pop-up de divulgação`,
  _ = `Mensagem pop-up de divulgação`,
  _ = `Banner de destaque`,
  _ = `Cápsula vertical de destaque`,
