  _ = `Tipo de conteúdo desconhecido: %1$s`,
  _ = `Erro: o ícone .PNG deve ser quadrado, com largura e altura iguais.`,
  _ = `Erro: o ícone .PNG deve ser quadrado, com pelo menos %1$s px de lado.`,
  _ = `%1$s ícone pendente`,
  _ = `%1$s ícones pendentes`,
  _ = `Os marcadores de linha do tempo devem ser publicados com as suas demais configurações do Steamworks.`,
  _ = `Ir para publicação`,
  _ = `Ícones públicos`,
  _ = `Eles podem ser acessados de todos os ramos, incluindo o ramo "default", por chamadas à API.`,
  _ = `Como ícones públicos, eles podem ser referenciados em outros lugares, portanto, não podem ser excluídos nem renomeados. Porém, é possível atualizar a imagem se necessário.`,
  _ = `Crie novos ícones com visibilidade "pública" caso deseje prepará-los para o lançamento público`,
  _ = `Ícones ocultos`,
  _ = `Use ícones ocultos para testar antes de torná-los publicamente visíveis. Use as configurações abaixo para associar ícones específicos a ramos específicos, caso precise limitar o acesso.`,
  _ = `Use ícones ocultos para testar antes de torná-los visíveis.`,
  _ = `não atribuído`,
  _ = `Estes ícones não serão exibidos em nenhuma versão`,
  _ = `Transformar todos os marcadores ocultos em públicos`,
  _ = `Baixar para testar localmente`,
