  _ = `Escolha um marcador publicado da lista abaixo para criar um clone no conjunto de ramos %1$s. Exclui os marcadores que já estão no conjunto.`,
  _ = `Marcador clonado com sucesso. `,
  _ = `Opcionalmente, associe a estes recursos um ou mais ramos. Qualquer usuário desses ramos poderá vê-los. Caso selecione algum ramo não protegido por senha, trataremos os ícones como visíveis publicamente.`,
  _ = `A lista de ramos não foi alterada`,
