  _ = `%1$s%`,
  _ = `Conjuntos de conquistas`,
  _ = `Use conjuntos para gerenciar as restrições de acesso e a visibilidade para conquistas. Por exemplo, você pode querer que um conjunto de conquistas esteja disponível apenas para proprietários de um conteúdo adicional.`,
