  _ = `Lançamento`,
  _ = `Testes`,
  _ = `Defina e atualize as conquistas do seu jogo.`,
  _ = `Para melhores resultados, os ícones das conquistas devem ser imagens em formato PNG de 256 x 256 px. Imagens de 64 x 64 px serão aceitas, mas recomendamos que usem imagens maiores. Também recomendamos que os ícones sejam em tons de cinza para conquistas que ainda não foram alcançadas e coloridos para as que já foram alcançadas.`,
  _ = `Conquistas aparecem em várias partes da Comunidade Steam, por isso os nomes e ícones devem ser apropriados para todas as idades e públicos. A Valve poderá remover da loja os jogos cujas conquistas violem as <1>diretrizes de conteúdo da comunidade</1> ou sejam ofensivas.`,
  _ = `Para ativar totalmente as conquistas e concluir os passos de lançamento, você também precisa ativar a opção correspondente na seção <1>Recursos disponíveis</1> do editor da página na loja.`,
